mapper.sql:
l.tenant_id = #{query.tenantId}
and l.deleted = 0

    and (
        l.title like concat('%', #{query.keyword}, '%')
        or l.content like concat('%', #{query.keyword}, '%')
        or l.target_user_name like concat('%', #{query.keyword}, '%')
        or l.target_email like concat('%', #{query.keyword}, '%')
        or l.error_message like concat('%', #{query.keyword}, '%')
    )


    and l.channel = #{query.channel}


    and l.target_scope = #{query.targetScope}


    and l.send_status = #{query.sendStatus}


    and l.created_at >= #{query.createdAtStart}


    and l.created_at <= #{query.createdAtEnd}

mapper.select:

select count(*)
from (
    select l.id
    from msg_delivery_log l
    where 
    order by l.created_at desc, l.id desc
    limit #{query.countLimit}
) delivery_log_candidates
